CREATE TABLE IF NOT EXISTS billing_upstream_channels (instance_id VARCHAR(64) NOT NULL,channel_id BIGINT NOT NULL,upstream_fp CHAR(64) NOT NULL,base_url VARCHAR(255) NOT NULL DEFAULT '',key_tail VARCHAR(8) NOT NULL DEFAULT '',channel_name VARCHAR(128) NOT NULL DEFAULT '',updated_at DATETIME(6) NOT NULL,PRIMARY KEY(instance_id,channel_id),KEY idx_upstream_fp(instance_id,upstream_fp)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
